sys_script_include.script:
var InsuranceUtils = Class.create();
InsuranceUtils.prototype = {
    initialize: function() {
    },
    getInsuranceByPatientID: function(id) {
        var insurance = new GlideRecord('u_insurance')
        insurance.addQuery('u_patient_id', id)
        insurance.query()
        return insurance
    },

    isPolicyActive: function(id) {
        var policy = new GlideRecord('u_insurance')
        if (policy.get(id)) {
            return policy.active == true
        }
        return false
    },

    getPolicyByID: function(id) {
        var policy = new GlideRecord('u_insurance');
        if (policy.get(id)) {
            return policy;
        }
        return null;
    },

    getPoliciesByProvider: function(providerName) {
        var policies = new GlideRecord('u_insurance');
        policies.addQuery('u_string_2', providerName); 
        policies.query();
        return policies; 
    },

    type: 'InsuranceUtils'
};
